INSERT INTO public.parameter_criteria_details VALUES (1, 1, 'Belum ada program penanaman budaya risiko, namun telah disusun peta jalan/rencana implementasi program penanaman budaya risiko (misal risk awards, kampanye, risk townhall, dan sebagainya)', 1, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL);
INSERT INTO public.parameter_criteria_details VALUES (2, 1, 'Telah ada program penanaman budaya risiko (misal risk awards, kampanye, risk townhall, dan sebagainya), namun saat ini dilakukan secara ad-hoc', 2, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL);
INSERT INTO public.parameter_criteria_details VALUES (3, 1, 'Telah ada program penanaman budaya risiko yang sedang dijalankan (misal risk awards, kampanye, risk townhall, dan sebagainya) dan terdapat program sadar risiko, saat ini dilakukan secara rutin (sekurang-kurangnya satu kali dalam setahun)', 3, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL);
INSERT INTO public.parameter_criteria_details VALUES (4, 1, 'Telah ada program penanaman budaya risiko yang sedang dijalankan (misal risk awards, kampanye, risk townhall, dan sebagainya) dan terdapat program sadar risiko, saat ini dilakukan secara rutin dan lebih sering (lebih dari satu kali dalam setahun)', 4, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL);
INSERT INTO public.parameter_criteria_details VALUES (5, 1, 'Telah ada program penanaman budaya risiko yang sedang dijalankan (misal risk awards, kampanye, risk townhall, dan sebagainya) dan terdapat program sadar risiko, saat ini dilakukan secara rutin dan lebih sering (lebih dari satu kali dalam setahun),', 5, '2025-05-05 04:51:27', '2025-05-05 04:51:27', NULL);
INSERT INTO public.parameter_criteria_details VALUES (6, 2, 'Budaya risiko belum tertanam di kegiatan usaha sehari-hari (misal kepemilikan dan tanggung jawab risiko pegawai dan jajaran manajemen belum jelas). Tanggung jawab pengembangan budaya risiko secara tidak langsung diemban oleh pegawai tertentu (misal unit kerja khusus), namun tidak ada keterlibatan Lini Kedua dan Direksi', 1, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL);
INSERT INTO public.parameter_criteria_details VALUES (7, 2, 'Tanggung jawab pengembangan  budaya Risiko diemban oleh Lini  Kedua namun tidak tercantum dengan jelas peran dan tanggung  jawab dalam uraian jabatan Lini Kedua', 2, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL);
INSERT INTO public.parameter_criteria_details VALUES (8, 2, 'Tanggung jawab pengembangan budaya Risiko secara jelas diemban oleh Lini Kedua dan sudah tercantum dengan jelas dalam uraian jabatan Lini Kedua, serta di awasi oleh Direksi dan Dewan Komisaris/ Dewan Pengawas', 3, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL);
INSERT INTO public.parameter_criteria_details VALUES (9, 2, 'Tanggung jawab pengembangan budaya Risiko secara jelas diemban oleh Lini Kedua  dan tercantum dalam uraian jabatan Lini  Kedua serta di awasi oleh Direksi dan Dewan Komisaris/ Dewan Pengawas', 4, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL);
INSERT INTO public.parameter_criteria_details VALUES (10, 2, 'Tanggung jawab pengembangan budaya risiko secara jelas diemban dan tercantum pada peran dan tanggung jawab jabatan tidak hanya untuk Lini Kedua, tetapi juga di semua lini (khususnya yang memegang posisi manajerial)', 5, '2025-05-05 04:52:09', '2025-05-05 04:52:09', NULL);
INSERT INTO public.parameter_criteria_details VALUES (11, 3, 'Direksi belum berperan aktif untuk mengembangkan budaya Manajemen Risiko', 1, '2025-05-05 04:53:04', '2025-05-05 04:53:04', NULL);
