INSERT INTO public.perlakuan_penyebab_monitorings VALUES (55, 40, 37, 0.00, 0.00, 'sudah menambahkan pasal di kontrak dengan vendor terkait komitmen pemenuhan TKDN harus sesuai dengan verifikasi dari Pihak Ketiga, dan apabila tidak memenuhi, akan dikenakan denda sesuai dengan selisih dari komitmen dikalikan dengan nilai kontrak pada saat negosiasi', NULL, '2026-01-30', '2026-01-30', '2026-01-06 06:51:33', '2026-01-06 06:51:33', NULL);
