INSERT INTO public.perlakuan_penyebab_monitorings VALUES (57, 41, 39, 90.00, 0.00, 'Menambah shift kerja', NULL, '2026-01-10', '2026-01-10', '2026-01-06 06:52:12', '2026-01-06 06:52:12', NULL);
INSERT INTO public.perlakuan_penyebab_monitorings VALUES (35, 20, 23, 60.00, 0.00, '1. Sudah meminta informasi aktual tentang batas lahan bebas pada waktu serah terima lahan
2. Sudah mengingatkan owner terkait lahan yang masih sengketa pada saat rapat mingguan
3. Sudah memberikan notifikasi melalui surat resmi ke owner bahwa akibat sengketa lahan tersebut berdampak pada schedule pekerjaan yang terlambat
4. Sudah melakukan pendekatan negosiasi dengan warga pemilik lahan
5. Sudah mengajukan prosedur proses approval desain ke Owner
6. Sudah mengingatkan konsultan pengawas dan Owner di setiap rapat mingguan untuk design drawing yang disubmit tetapi sudah melewati masa waktu approval
4. Mulai menyusun dokumen untuk pengajuan eot dan klaim atas lahan sengketa
6. Sudah melakukan koordinasi dan komunikasi rutin dengan owner yang mengurusi terkait dokumen eot dan klaim
7. Owner sudah menyampaikan bahwa semua lahan sudah bebas
', NULL, '2025-08-01', '2025-08-01', '2025-12-10 10:00:18', '2025-12-10 10:00:18', NULL);
INSERT INTO public.perlakuan_penyebab_monitorings VALUES (36, 21, 23, 47.00, 0.00, '1. Memanggil konsultan design yang bermula berkantor di Jakarta untuk berkantor di Site (D2 & D3)
2. Sudah melakukan konsinyering dengan konsultan pengawas dan Owner setelah design disubmit ke Owner (D2 & D3)
3. Sedang menyiapkan biaya percepatan pekerjaan (D2 & D3)
4. Sedang menyiapkan klaim EOT dan tambahan biaya ke Owner (D1, D2 & D3)', NULL, '2025-06-11', '2025-06-11', '2025-12-10 10:00:18', '2025-12-10 10:00:18', NULL);
INSERT INTO public.perlakuan_penyebab_monitorings VALUES (37, 24, 24, 25.00, 0.00, '1. Sudah meminta konsultan desain untuk melakukan optimasi desain bore pile supaya tidak mengurangi volume
