INSERT INTO public.strategi_bisnis VALUES (1, 1, 'Manajemen Risiko & Darurat – Identifikasi, pengendalian, simulasi bencana alam, serta kajian geoteknik dan klaim force majeure. Evaluasi & Pendampingan Proyek – Evaluasi intensif proyek bermasalah, pendampingan RAB, monitoring rutin, koordinasi dengan Owner, serta eskalasi ke Direksi bila perlu. Pengadaan & Kontrak – Maksimalkan kontrak/pembelian awal, negosiasi pembayaran pra-kontrak, dan penggunaan supplier lokal/regional. Perizinan & Vendor – Pastikan perizinan sebelum mulai pekerjaan dan gunakan VPI untuk evaluasi vendor. Anggaran & Logistik – Monitor kecukupan anggaran dan logistik secara real-time.', 1, '2025-11-09 12:11:44', '2025-11-20 03:53:31', NULL);


